(3312, '_transient_ut-overlay-navigation-css', '<style id=\"ut-overlay-custom-css\" type=\"text/css\">.ut-open-overlay-menu.ut-hamburger:hover {opacity: 0.3;} .ut-open-overlay-menu.ut-hamburger span, .ut-open-overlay-menu.ut-hamburger span::before,.ut-open-overlay-menu.ut-hamburger span::after {height: 2px;} .ut-open-overlay-menu.ut-hamburger span::before,.ut-open-overlay-menu.ut-hamburger span::after {width: 100%;} #ut-overlay-nav ul > li { font-family: ralewaysemibold ;}#ut-overlay-nav ul.sub-menu > li { letter-spacing: normal; }</style>', 'off'),
(3313, '_transient_timeout_ut-overlay-search-css', '1758565297', 'off'),
(3314, '_transient_ut-overlay-search-css', '<style id=\"ut-overlay-search-css\" type=\"text/css\"></style>', 'off'),
(3315, '_transient_timeout_ut-theme-sidebar-css', '1758565297', 'off'),
(3316, '_transient_ut-theme-sidebar-css', '<style type=\"text/css\">#primary { float: left ; }#ut-sitebody #secondary .widget-title,#ut-sitebody #secondary .widget-title a,#ut-sitebody #secondary .widget-title a:hover,#ut-sitebody #secondary .widget-title a:active,#ut-sitebody #secondary h1,#ut-sitebody #secondary h2,#ut-sitebody #secondary h3,#ut-sitebody #secondary h4,#ut-sitebody #secondary h5,#ut-sitebody #secondary h6 {color:#151515 !important;}#ut-sitebody #secondary,#ut-sitebody #secondary select,#ut-sitebody #secondary textarea,#ut-sitebody #secondary input[type=\"text\"],#ut-sitebody #secondary input[type=\"tel\"],#ut-sitebody #secondary input[type=\"email\"],#ut-sitebody #secondary input[type=\"password\"],#ut-sitebody #secondary input[type=\"number\"],#ut-sitebody #secondary input[type=\"search\"],#ut-sitebody #secondary .ut_widget_social ul.ut-sociallinks span {font-size:12px !important;}#ut-sitebody #secondary { line-height:24px !important;}#ut-sitebody #secondary h3.widget-title,#ut-sitebody .ut-footer-area h2.wp-block-heading {font-family:\"Oswald\" ; font-weight: 700 ; font-size: 16px ;}</style>', 'off'),
(3317, '_transient_timeout_ut-theme-option-css', '1758565298', 'off'),
(3318, '_transient_ut-theme-option-css', '<style id=\"ut-theme-option-css\" type=\"text/css\">.widget-title span{color:#333 !important;}</style>', 'off'),
